  observe_files?: Array<string>;
}): Promise<CallToolResult>; };
```"},{"name":"mcp__ortg__ortg_overview","description":"对账并返回纲要与全库计数摘要，完整路径清单用 ortg_status 按需查看。不带参数时整份不超过整份预算（估算的 token 不超过上下文窗口的一半，大小不超过约 48 万（单次截断值 50 万留出余量，Claude 按字计、Codex 按 token 计））就整份返回，超过时只返回纲要头与模块清单（不含条目正文）；再用 module（B 标签）取模块，module="*" 取全部。同一会话只发上下文里还没有或已变动的条目，全都发过就只回计数摘要；上下文压缩或清空后自动重发；确实看不到时传 force=true 重发。一次超过单次上限时照发正文（可能被截断），开头提醒把模块拆细。本仓库启用了 ORTG（会话开始注入过 ORTG 纲要规则）时开工先调用。仓库没有 ortg.tsv 就是没启用 ORTG：不要调用 ortg 工具；只有用户明确要求创建（初始化）或对齐纲要时，才传 init=true 建表（根目录有 overview.txt 则先备份再整份导入，否则建空表；再首扫）。 任务纲要生成：普通任务先显式用 ortg_header mode=task。先读原任务和可见测试，列出相关仓库相对路径及关联理由，再逐份读正文，仅生成或修订任务和测试有关文件的纲要。沿合法公共对象的构造或获取、目标调用、输出及实际依赖，将必要 helper 和消费者动态纳入。已有有据且对齐的纲要复用，不为凑全库覆盖补无关文件；未相关裸行保持未知，不宣称全库 ready。可见测试缺失时，依据公开接口和可见调用方形成候选并标未验证，不用隐藏评测、gold 或历史失败答案推范围。相关名单只限定纲要生成，不缩小任务、源码、角色或测试评测范围；保留原库存与已有真实纲要，不通过改忽略/观察角色隐藏无关文件。只有用户明确要求全库初始化才用 mode=build。
Codex 宿主补充：本宿主用 functions.exec 包装 MCP 调用，工具结果超过预算会被从中间截掉、只留首尾——不报错，被截掉的文件你根本不知道存在。故调用 ortg_overview 时，外层命令第一行必须是 // @exec: {"max_output_tokens": 500000}；它只抬高这一次工具结果的预算，不是模型输出上限，也不改纲要内容。ortg_overview 的每种回复（模块或文件的纲要、模块清单、短回复）最后一行都是以"以上"开头的收尾句，正文里也不会有 "tokens truncated" 字样；最后一行不是这样，或中间出现 "…N tokens truncated…"，就是被截断了：照此重发一次并传 force=true（本会话已计为发过，不传只会拿到短回复）。重发仍被截断，多半是 ~/.codex/config.toml 没设 tool_output_token_limit = 500000（不设时 Codex 存进对话的工具结果只留约 1.2 万 token，@exec 抬不过它）或 [mcp_servers.ortg] 没设 env = { ORTG_AGENT = "codex" }：告诉用户按 ortg 的 README 补上后重启 Codex，在此之前按模块分次取。自定义 CODEX_HOME 要在 MCP 配置设 env_vars = ["CODEX_HOME"]；Linux 未转交时 ORTG 只沿当前进程祖先链找该变量，再回退 ~/.codex。不要拿半份纲要开工，也不要用 Grep/Read 去补缺失的部分。

exec tool declaration:
```ts
declare const tools: { mcp__ortg__ortg_overview(args: {
  // 本会话已发过的条目也重发；只在上下文里确实看不到它们时用
  force?: boolean;
  // 仓库还没有 ortg.tsv 时建表；只在用户明确要求创建（初始化）或对齐纲要时传 true
  init?: boolean;
  // 只看这个模块(纲要行 B 标签)；"*" 取全部；留空按整份预算给整份或模块清单
  module?: string;
}): Promise<CallToolResult>; };
```"},{"name":"mcp__ortg__ortg_review","description":"核对改动计划（参数 rulings：对上一次核对给了正文的每条契约写一行「契约键：裁决」，缺了不收敛）：列出所有目标纲要（要改、新建、删除的文件）的现在→目标字段变化、不合格的目标行、Uses 依赖它们却还没有目标纲要的文件，并给出逐项核对清单。要改多个文件时，写完计划后调用；核对列出要补、要核实的地方时，补改后连续两次看到同一计划才解锁，计划全写 = 或核对没发现要补的地方时一次即解锁。只改一个文件不需要。只给自己核对用，不用给用户看。

exec tool declaration:
```ts
declare const tools: { mcp__ortg__ortg_review(args: {
  // 对上一次核对给了正文的每条契约写一行「契约键：裁决」（需求是否讲到这个场景、与守护测试一致还是相反、按哪条证据裁决）；缺了裁决计划不收敛
  rulings?: Array<string>;
