import json
import logging
import re
import string
import warnings
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import asdict
from inspect import Parameter, Signature
from tempfile import TemporaryDirectory
from typing import Any

import numpy as np
import pandas as pd

import mlflow
from mlflow.exceptions import MlflowException
from mlflow.metrics.base import MetricValue
from mlflow.metrics.genai import model_utils
from mlflow.metrics.genai.base import EvaluationExample
from mlflow.metrics.genai.prompt_template import PromptTemplate
from mlflow.metrics.genai.utils import (
    _MIGRATION_GUIDE,
    _get_default_model,
    _get_latest_metric_version,
)
from mlflow.models import EvaluationMetric, make_metric

from mlflow.protos.databricks_pb2 import (
    BAD_REQUEST,
    INTERNAL_ERROR,
    INVALID_PARAMETER_VALUE,
    UNAUTHENTICATED,
    ErrorCode,
)
from mlflow.utils.annotations import deprecated
from mlflow.utils.class_utils import _get_class_from_string

from mlflow.version import VERSION

_logger = logging.getLogger(__name__)

_GENAI_CUSTOM_METRICS_FILE_NAME = "genai_custom_metrics.json"
_PROMPT_FORMATTING_WRAPPER = """

You must return the following fields in your response in two lines, one below the other:
score: Your numerical score based on the rubric
justification: Your reasoning for giving this score

Do not add additional new lines. Do not add any other fields."""






























# Function to extract Score and Justification


def _extract_score_and_justification(text):
    if not text:
        return None, None

    failure = f"Failed to extract score and justification from model output: {text}"
    try:
        response = json.loads(text)
    except json.JSONDecodeError:
        match = re.search(
            r"score:\s*(\d+)\s*,?\s*justification:\s*(.+)",
            text,
            flags=re.IGNORECASE | re.DOTALL,
        )
        if match is None:
            return None, failure
        return int(match.group(1)), match.group(2).strip()

    response = {key.lower(): value for key, value in response.items()}
    score = int(response["score"])
    justification = response["justification"]
    if not isinstance(justification, str):
        return None, failure
    return score, justification


def _format_args_string(grading_context_columns: list[str] | None, eval_values, indx) -> str:
    formatted = []
    for column in grading_context_columns:
        if column not in eval_values:
            raise MlflowException(
                f"Missing grading context column '{column}'. Available columns: "
                f"{list(eval_values.keys())}",
                error_code=INVALID_PARAMETER_VALUE,
            )
        values = eval_values[column]
        value = values.iloc[indx] if isinstance(values, pd.Series) else values[indx]
        formatted.append(f"key: {column}\nvalue:\n{value}")

    if not formatted:
        return ""
    return "Additional information used by the model:\n" + "\n".join(formatted)




























def _score_model_on_one_payload(
    payload: str,
    eval_model: str,
    parameters: dict[str, Any] | None,
    extra_headers: dict[str, str] | None = None,
    proxy_url: str | None = None,
):
    try:
        # If the endpoint does not specify type, default to chat format
        endpoint_type = model_utils.get_endpoint_type(eval_model) or "llm/v1/chat"
        raw_result = model_utils.score_model_on_payload(
            eval_model, payload, parameters, extra_headers, proxy_url, endpoint_type
        )
        return _extract_score_and_justification(raw_result)
    except ImportError:
        raise
    except MlflowException as e:
        if e.error_code in [
            ErrorCode.Name(BAD_REQUEST),
            ErrorCode.Name(UNAUTHENTICATED),
            ErrorCode.Name(INVALID_PARAMETER_VALUE),
        ]:
            raise
        else:
            return None, f"Failed to score model on payload. Error: {e!s}"
    except Exception as e:
        return None, f"Failed to score model on payload. Error: {e!s}"


_DEFAULT_AGGREGATIONS = ["mean", "variance", "p90"]
_DEFAULT_PARAMETERS = {"temperature": 0.0, "max_tokens": 200, "top_p": 1.0}


def _value_at(values, index):
    if isinstance(values, pd.Series):
        return values.iloc[index]
    return values[index]


def _aggregate_scores(scores, aggregations):
    numeric_scores = np.asarray([score for score in scores if score is not None], dtype=float)
    aggregate_functions = {
        "min": lambda values: np.min(values),
        "max": lambda values: np.max(values),
        "mean": lambda values: np.mean(values),
        "median": lambda values: np.median(values),
        "variance": lambda values: np.var(values),
        "p90": lambda values: np.percentile(values, 90),
    }
    unsupported = [name for name in aggregations if name not in aggregate_functions]
    if unsupported:
        raise MlflowException(
            f"Unsupported aggregations: {unsupported}. Supported aggregations are: "
            f"{list(aggregate_functions)}",
            error_code=INVALID_PARAMETER_VALUE,
        )
    if numeric_scores.size == 0:
        return {name: float("nan") for name in aggregations}
    return {name: aggregate_functions[name](numeric_scores) for name in aggregations}


def _score_payloads(payloads, model, parameters, max_workers, extra_headers, proxy_url):
    scores = [None] * len(payloads)
    justifications = [None] * len(payloads)
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {
            executor.submit(
                _score_model_on_one_payload,
                payload,
                model,
                parameters,
                extra_headers,
                proxy_url,
            ): index
            for index, payload in enumerate(payloads)
        }
        for future in as_completed(futures):
            index = futures[future]
            scores[index], justifications[index] = future.result()
    return scores, justifications


def _serialized_examples(examples):
    return None if examples is None else [asdict(example) for example in examples]


@deprecated(since="3.4.0", impact=_MIGRATION_GUIDE)
def make_genai_metric(
    name: str,
    definition: str,
    grading_prompt: str,
    examples: list[EvaluationExample] | None = None,
    version: str | None = _get_latest_metric_version(),
    model: str | None = _get_default_model(),
    grading_context_columns: str | list[str] | None = None,
    include_input: bool = True,
    parameters: dict[str, Any] | None = None,
    aggregations: list[str] | None = None,
    greater_is_better: bool = True,
    max_workers: int = 10,
    metric_metadata: dict[str, Any] | None = None,
    extra_headers: dict[str, str] | None = None,
    proxy_url: str | None = None,
) -> EvaluationMetric:
    if isinstance(grading_context_columns, str):
        grading_context_columns = [grading_context_columns]
    elif not grading_context_columns:
        grading_context_columns = []
    elif not isinstance(grading_context_columns, list) or not all(
        isinstance(column, str) for column in grading_context_columns
    ):
        raise MlflowException(
            "`grading_context_columns` must be a string, a list of strings, or None.",
            error_code=INVALID_PARAMETER_VALUE,
        )

    reserved_names = {"predictions", "metrics", "inputs"}
    malformed_columns = [
        column
        for column in grading_context_columns
        if not column.isidentifier() or column in reserved_names
    ]
    if malformed_columns or len(set(grading_context_columns)) != len(grading_context_columns):
        raise MlflowException(
            "Grading context columns must be unique valid Python identifiers and cannot use "
            f"reserved metric argument names. Invalid columns: {malformed_columns}",
            error_code=INVALID_PARAMETER_VALUE,
        )

    for example in examples or []:
        context = example.grading_context
        if context is not None and not isinstance(context, dict):
            context = {grading_context_columns[0]: context}
            example.grading_context = context
        elif context is None:
            context = {}

        if set(context) != set(grading_context_columns):
            raise MlflowException(
                "Each example's grading context keys must exactly match "
                f"grading_context_columns. Expected {grading_context_columns}, got "
                f"{list(context)}.",
                error_code=INVALID_PARAMETER_VALUE,
            )

    evaluation_model_path = f"mlflow.metrics.genai.prompts.{version}.EvaluationModel"
    try:
        evaluation_model_class = _get_class_from_string(evaluation_model_path)
    except ModuleNotFoundError:
        raise MlflowException(
            f"Failed to find GenAI metric version {version}.",
            error_code=INVALID_PARAMETER_VALUE,
        ) from None
    except Exception as e:
        raise MlflowException(
            f"Failed to construct GenAI metric version {version}. Error: {e!r}",
            error_code=INTERNAL_ERROR,
        ) from None

    evaluation_model_args = {
        "name": name,
        "definition": definition,
        "grading_prompt": grading_prompt,
        "examples": examples,
        "include_input": include_input,
    }
    if model is not None:
        evaluation_model_args["model"] = model
    if parameters is not None:
        evaluation_model_args["parameters"] = parameters
    try:
        evaluation_model = evaluation_model_class(**evaluation_model_args).to_dict()
    except Exception as e:
        raise MlflowException(
            f"Failed to construct GenAI metric version {version}. Error: {e!r}",
            error_code=INTERNAL_ERROR,
        ) from None
    eval_prompt = evaluation_model["eval_prompt"]
    model = evaluation_model["model"]
    parameters = evaluation_model["parameters"]
    aggregations = aggregations or list(_DEFAULT_AGGREGATIONS)

    def eval_fn(predictions, metrics, inputs, *args):
        eval_values = dict(zip(grading_context_columns, args))
        payloads = []
        for index in range(len(predictions)):
            payloads.append(
                eval_prompt.format(
                    input=_value_at(inputs, index) if inputs is not None else None,
                    output=_value_at(predictions, index),
                    grading_context_columns=_format_args_string(
                        grading_context_columns, eval_values, index
                    ),
                )
            )
        scores, justifications = _score_payloads(
            payloads, model, parameters, max_workers, extra_headers, proxy_url
        )
        return MetricValue(
            scores=scores,
            justifications=justifications,
            aggregate_results=_aggregate_scores(scores, aggregations),
        )

    eval_fn.__signature__ = Signature(
        [
            Parameter("predictions", Parameter.POSITIONAL_OR_KEYWORD),
            Parameter("metrics", Parameter.POSITIONAL_OR_KEYWORD),
            Parameter("inputs", Parameter.POSITIONAL_OR_KEYWORD),
            *[
                Parameter(column, Parameter.POSITIONAL_OR_KEYWORD)
                for column in grading_context_columns
            ],
        ]
    )

    genai_metric_args = {
        "name": name,
        "definition": definition,
        "grading_prompt": grading_prompt,
        "examples": _serialized_examples(examples),
        "version": version,
        "model": model,
        "grading_context_columns": grading_context_columns,
        "include_input": include_input,
        "parameters": parameters,
        "aggregations": aggregations,
        "greater_is_better": greater_is_better,
        "max_workers": max_workers,
        "metric_metadata": metric_metadata,
        "extra_headers": extra_headers,
        "proxy_url": proxy_url,
        "fn_name": make_genai_metric.__name__,
        "mlflow_version": VERSION,
    }
    return make_metric(
        eval_fn=eval_fn,
        name=name,
        greater_is_better=greater_is_better,
        version=version,
        metric_details="".join(eval_prompt.template_strs),
        metric_metadata=metric_metadata,
        genai_metric_args=genai_metric_args,
        _require_strict_signature=True,
    )


@deprecated(since="3.4.0", impact=_MIGRATION_GUIDE)
def make_genai_metric_from_prompt(
    name: str,
    judge_prompt: str | None = None,
    model: str | None = _get_default_model(),
    parameters: dict[str, Any] | None = None,
    aggregations: list[str] | None = None,
    greater_is_better: bool = True,
    max_workers: int = 10,
    metric_metadata: dict[str, Any] | None = None,
    extra_headers: dict[str, str] | None = None,
    proxy_url: str | None = None,
) -> EvaluationMetric:
    if not isinstance(judge_prompt, str):
        raise TypeError("`judge_prompt` must be a string.")

    parameters = dict(_DEFAULT_PARAMETERS) if parameters is None else parameters
    aggregations = aggregations or list(_DEFAULT_AGGREGATIONS)
    formatter = string.Formatter()
    prompt_variables = []
    for _, field_name, _, _ in formatter.parse(judge_prompt):
        if field_name is None:
            continue
        variable = field_name.split(".", 1)[0].split("[", 1)[0]
        if variable not in prompt_variables:
            prompt_variables.append(variable)
    invalid_variables = [name for name in prompt_variables if not name.isidentifier()]
    if invalid_variables:
        raise MlflowException(
            f"Judge prompt variables must be valid Python identifiers: {invalid_variables}",
            error_code=INVALID_PARAMETER_VALUE,
        )

    prompt_template = PromptTemplate(judge_prompt + _PROMPT_FORMATTING_WRAPPER)

    def eval_fn(*args, **kwargs):
        eval_values = kwargs or dict(zip(prompt_variables, args))
        if eval_values:
            first_values = next(iter(eval_values.values()))
            if isinstance(first_values, str):
                row_count = 1
            else:
                row_count = len(first_values)
        else:
            row_count = 1

        payloads = []
        for index in range(row_count):
            row_values = {
                variable: (
                    values
                    if isinstance(values, str)
                    else _value_at(values, index)
                )
                for variable, values in eval_values.items()
            }
            payloads.append(prompt_template.format(**row_values))

        scores, justifications = _score_payloads(
            payloads, model, parameters, max_workers, extra_headers, proxy_url
        )
        return MetricValue(
            scores=scores,
            justifications=justifications,
            aggregate_results=_aggregate_scores(scores, aggregations),
        )

    eval_fn.__signature__ = Signature(
        [Parameter(variable, Parameter.POSITIONAL_OR_KEYWORD) for variable in prompt_variables]
    )
    genai_metric_args = {
        "name": name,
        "judge_prompt": judge_prompt,
        "model": model,
        "parameters": parameters,
        "aggregations": aggregations,
        "greater_is_better": greater_is_better,
        "max_workers": max_workers,
        "metric_metadata": metric_metadata,
        "extra_headers": extra_headers,
        "proxy_url": proxy_url,
        "fn_name": make_genai_metric_from_prompt.__name__,
        "mlflow_version": VERSION,
    }
    return make_metric(
        eval_fn=eval_fn,
        name=name,
        greater_is_better=greater_is_better,
        metric_details=judge_prompt + _PROMPT_FORMATTING_WRAPPER,
        metric_metadata=metric_metadata,
        genai_metric_args=genai_metric_args,
    )

