# NB: we need this function because we cannot modify the signature of
# a class's __call__ method after the class has been defined.
# This is also useful to distinguish between the metric signatures with different eval_fn signatures


def _generate_eval_metric_class(eval_fn, require_strict_signature=False):
    eval_signature = inspect.signature(eval_fn)
    eval_parameters = [
        parameter
        for parameter in eval_signature.parameters.values()
        if parameter.kind not in (Parameter.VAR_POSITIONAL, Parameter.VAR_KEYWORD)
    ]
    parameter_names = [parameter.name for parameter in eval_parameters]

    def _to_series(value, argument_name):
        if value is None or isinstance(value, pd.Series):
            return value
        if isinstance(value, str):
            return pd.Series([value])
        if isinstance(value, list):
            return pd.Series(value)
        raise TypeError(
            f"Expected `{argument_name}` to be a pandas Series, string, list, or None, "
            f"but got {type(value).__name__}."
        )

    def _call_method(self, *args, **kwargs):
        if args:
            raise TypeError("Evaluation metrics only accept keyword arguments.")

        if not require_strict_signature:
            return self.eval_fn(**kwargs)

        expected = set(parameter_names)
        unexpected = set(kwargs) - expected
        additional_names = parameter_names[3:]
        missing = [name for name in additional_names if name not in kwargs]
        if unexpected or missing:
            details = []
            if missing:
                details.append(f"missing arguments: {missing}")
            if unexpected:
                details.append(f"unexpected arguments: {sorted(unexpected)}")
            raise MlflowException(
                "Invalid arguments for the GenAI evaluation metric (" + "; ".join(details) + ").",
                error_code=INVALID_PARAMETER_VALUE,
            )

        predictions = _to_series(kwargs.get("predictions"), "predictions")
        metrics = kwargs.get("metrics") or {}
        inputs = _to_series(kwargs.get("inputs"), "inputs")
        additional_values = [
            _to_series(kwargs[name], name)
            for name in additional_names
        ]
        return self.eval_fn(predictions, metrics, inputs, *additional_values)

    call_parameters = [Parameter("self", Parameter.POSITIONAL_OR_KEYWORD)]
    for parameter in eval_parameters:
        call_parameters.append(parameter.replace(kind=Parameter.KEYWORD_ONLY))
    _call_method.__signature__ = Signature(
        call_parameters,
        return_annotation=eval_signature.return_annotation,
    )

    class CallableEvaluationMetric(EvaluationMetric):
        __call__ = _call_method

    return CallableEvaluationMetric


